// Rookery service worker: caches the whole app on first load so it works offline.
// The file list comes from precache.json (generated by scripts/gen-precache.mjs).
const CACHE_PREFIX = 'rookery-';
const UPLOADS_CACHE = 'rookeryuploads'; // not prefixed with 'rookery-' so version clean-up keeps it

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const res = await fetch('precache.json', { cache: 'no-store' });
    const { version, files } = await res.json();
    const cache = await caches.open(CACHE_PREFIX + version);
    await cache.addAll(files.map((f) => new Request(f, { cache: 'reload' })));
    self.__version = version;
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const res = await fetch('precache.json', { cache: 'no-store' }).catch(() => null);
    const current = res ? CACHE_PREFIX + (await res.json()).version : null;
    for (const key of await caches.keys()) {
      if (key.startsWith(CACHE_PREFIX) && key !== current) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const base = new URL('./', self.registration.scope).pathname;
  const path = url.pathname.slice(base.length);
  // Never cache the optional admin server's API or the /admin panel; they must always reach the network.
  if (path.startsWith('api/') || path === 'admin' || path.startsWith('admin/')) return;
  // Piece images uploaded through the admin panel: cached on first use so custom piece sets also work offline.
  if (path.startsWith('uploads/')) {
    event.respondWith((async () => {
      const cache = await caches.open(UPLOADS_CACHE);
      const hit = await cache.match(req);
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    })());
    return;
  }
  event.respondWith((async () => {
    const cached = await caches.match(req, { ignoreSearch: true });
    if (cached) return cached;
    try {
      const res = await fetch(req);
      return res;
    } catch (e) {
      // offline navigation -> app shell
      if (req.mode === 'navigate') {
        const shell = await caches.match('index.html');
        if (shell) return shell;
      }
      throw e;
    }
  })());
});
